SQL_DOC.P_SQL:
DECLARE
V_COUNT NUMBER;
BEGIN
V_COUNT := 0;
SELECT COUNT(*) INTO V_COUNT FROM KEPRQHD WHERE PLANT = $PLANT$ AND QUOTATION_NO = $QUOTATION_NO$ AND QUOTATION_SEQ = $QUOTATION_SEQ$ AND REVISION_NO = $REVISION_NO$ ;
IF V_COUNT=0 THEN
INSERT INTO KEPRQHD( PLANT, QUOTATION_NO, QUOTATION_SEQ, REVISION_NO, STATUS, BUYER_ITEM_NO, UNIT_PRICE, KEP_USER_NAME, KEP_USER_TELNO, KEP_USER_MAIL, KEP_ITEM_DESC, KEP_ITEM_SPEC, KEP_ITEM_UOM, ADD_DATE, ADD_TIME )VALUES( $PLANT$, $QUOTATION_NO$, $QUOTATION_SEQ$, $REVISION_NO$, $STATUS$, $BUYER_ITEM_NO$, NVL($UNIT_PRICE$,0), $KEP_USER_NAME$, $KEP_USER_TELNO$, $KEP_USER_MAIL$, $KEP_ITEM_DESC$, $KEP_ITEM_SPEC$, $KEP_ITEM_UOM$, TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS') );
ELSE
UPDATE KEPRQHD SET STATUS = $STATUS$, BUYER_ITEM_NO = $BUYER_ITEM_NO$, UNIT_PRICE = NVL($UNIT_PRICE$,0), KEP_USER_NAME = $KEP_USER_NAME$, KEP_USER_TELNO = $KEP_USER_TELNO$, KEP_USER_MAIL = $KEP_USER_MAIL$, KEP_ITEM_DESC = $KEP_ITEM_DESC$, KEP_ITEM_SPEC = $KEP_ITEM_SPEC$, KEP_ITEM_UOM = $KEP_ITEM_UOM$, IF_FLAG = 'N', ADD_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), ADD_TIME = TO_CHAR(SYSDATE,'HH24MISS') WHERE PLANT = $PLANT$ AND QUOTATION_NO = $QUOTATION_NO$ AND QUOTATION_SEQ = $QUOTATION_SEQ$ AND REVISION_NO = $REVISION_NO$ ;
END IF;
END;
